export type ParsedPipelineInitMarketInstruction<
  TProgram extends string = typeof TAX_AMM_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The router's market PDA for this market state. */
    marketSigner: TAccountMetas[0];
    /**
     * A fresh keypair the creator generated, which signs (metadata `new_keypair`). The
     * router passes its signature on only while the account is empty and unfunded.
     */
    marketState: TAccountMetas[1];
    /**
     * A router PDA holding the SOL the creator allowed for setup. Rent comes from it; the
     * router returns what is left to the creator.
     */
    payer: TAccountMetas[2];
    systemProgram: TAccountMetas[3];
    mint0: TAccountMetas[4];
    mint1: TAccountMetas[5];
    authority: TAccountMetas[6];
    vault0: TAccountMetas[7];
    vault1: TAccountMetas[8];
    tokenProgram0: TAccountMetas[9];
    tokenProgram1: TAccountMetas[10];
  };
  data: PipelineInitMarketInstructionData;
};

export function parsePipelineInitMarketInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPipelineInitMarketInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      marketSigner: getNextAccount(),
      marketState: getNextAccount(),
      payer: getNextAccount(),
      systemProgram: getNextAccount(),
      mint0: getNextAccount(),
      mint1: getNextAccount(),
      authority: getNextAccount(),
      vault0: getNextAccount(),
      vault1: getNextAccount(),
      tokenProgram0: getNextAccount(),
      tokenProgram1: getNextAccount(),
    },
    data: getPipelineInitMarketInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
